<template>
  <section class="return-form-page">
    <template v-if="kind === 'purchase'">
      <div class="design-action-row">
        <span class="design-crumb">采购管理　/　采购退货　/　<b>新建采购退货单</b></span>
        <div><el-button size="small" icon="el-icon-back" @click="$router.push(basePath)">返回列表</el-button><el-button size="small" class="draft-button" :loading="saving" @click="save(false)">保存草稿</el-button><el-button size="small" type="success" :loading="saving" @click="save(true)">保存并提交</el-button></div>
      </div>

      <div class="purchase-layout">
        <main class="purchase-main">
          <div class="card purchase-header-card">
            <el-form label-position="top" size="small" class="purchase-header-form">
              <el-form-item label="退货单号"><el-input value="保存时按编号规则生成" disabled /></el-form-item>
              <el-form-item label="退货日期"><el-date-picker v-model="form.return_date" value-format="yyyy-MM-dd" style="width:100%" /></el-form-item>
              <el-form-item label="供应商" required><el-input :value="selectedSource && selectedSource.supplier_name" placeholder="选择原到货批次后带出" disabled /></el-form-item>
              <el-form-item label="退货原因" required><el-select v-model="form.return_reason" placeholder="请选择退货原因" style="width:100%"><el-option v-for="reason in purchaseReasons" :key="reason" :label="reason" :value="reason" /></el-select></el-form-item>
              <el-form-item class="remark-field" label="备注"><el-input v-model.trim="form.remark" type="textarea" :rows="2" maxlength="200" show-word-limit placeholder="请输入备注（非必填）" /></el-form-item>
            </el-form>
          </div>

          <div class="card source-card purchase-source-card">
            <div class="section-heading"><h3>选择原采购到货批次</h3></div>
            <div class="source-toolbar"><el-input v-model="sourceQuery.keyword" size="small" clearable prefix-icon="el-icon-search" placeholder="请输入到货单号/采购订单号/物料编码/物料名称进行搜索" @keyup.enter.native="reloadSources" /><el-button size="small" icon="el-icon-refresh" @click="reloadSources">刷新</el-button></div>
            <el-table v-loading="loading" :data="sources" border size="mini" highlight-current-row>
              <el-table-column label="选择" width="58" align="center"><template slot-scope="{row}"><el-tooltip :disabled="!purchaseSourceBlocked(row)" :content="purchaseSourceBlockedReason(row)" placement="top"><span><el-checkbox :value="isPurchaseSourceSelected(row)" :disabled="purchaseSourceBlocked(row)" @change="togglePurchaseSource(row,$event)" /></span></el-tooltip></template></el-table-column>
              <el-table-column prop="receipt_no" label="到货单" min-width="128" />
              <el-table-column prop="purchase_order_no" label="采购订单" min-width="128" />
              <el-table-column label="物料编码/名称" min-width="190"><template slot-scope="{row}"><div>{{ row.item_code }} / {{ row.item_name }}</div><div v-if="row.serial_tracking_mode==='required'" :class="['source-serial-hint',{blocked:purchaseSourceSerialBlocked(row)}]">可用编号 {{ row.available_serial_count }} 个</div></template></el-table-column>
              <el-table-column prop="warehouse_name" label="仓库" min-width="92" />
              <el-table-column prop="location_name" label="库位" min-width="92" />
              <el-table-column prop="batch_no" label="批次" min-width="132" />
              <el-table-column prop="posted_base_qty" label="已入库" width="86" align="right" />
              <el-table-column prop="reserved_return_base_qty" label="已占用退货" width="98" align="right" />
              <el-table-column prop="current_available_base_qty" label="当前可用库存" width="108" align="right" />
              <el-table-column prop="available_return_base_qty" label="可退数量" width="92" align="right" />
            </el-table>
            <el-pagination background layout="total, prev, pager, next, sizes, jumper" :current-page.sync="sourceQuery.page" :page-size.sync="sourceQuery.per_page" :page-sizes="[10,20,50]" :total="sourceTotal" @current-change="loadSources" @size-change="reloadSources" />
          </div>

          <div class="card selected-card purchase-selected-card">
            <div class="section-heading"><h3>已选择的退货明细</h3></div>
            <el-table :data="selectedLines" border size="mini">
              <el-table-column type="index" label="序号" width="56" align="center" />
              <el-table-column prop="receipt_no" label="到货单" min-width="125" />
              <el-table-column prop="purchase_order_no" label="采购订单" min-width="125" />
              <el-table-column label="物料编码/名称" min-width="190"><template slot-scope="{row}">{{ row.item_code }} / {{ row.item_name }}</template></el-table-column>
              <el-table-column label="仓库" min-width="86"><template slot-scope="{row}">{{ row.warehouse_name }}</template></el-table-column>
              <el-table-column label="库位" min-width="86"><template slot-scope="{row}">{{ row.location_name }}</template></el-table-column>
              <el-table-column prop="batch_no" label="批次" min-width="125" />
              <el-table-column label="实际可退数量" width="176" align="right"><template slot-scope="{row}"><div class="qty-main">{{ formatQty(purchaseReturnMax(row), returnUnitPrecision(row)) }} {{ returnUnitName(row) }}</div><div v-if="Number(row.return_conversion_factor||1)!==1" class="qty-conversion-hint">折合 {{ formatQty(purchaseReturnMax(row)*Number(row.return_conversion_factor||1), baseUnitPrecision(row)) }} {{ row.base_unit_name }}<template v-if="purchaseReturnRemainder(row)>0">；另余 {{ formatQty(purchaseReturnRemainder(row), baseUnitPrecision(row)) }} {{ row.base_unit_name }}需改用基本单位</template></div></template></el-table-column>
              <el-table-column label="退货单位" width="112"><template slot-scope="{row}"><el-select v-model="row.return_unit_id" size="mini" @change="changePurchaseReturnUnit(row, $event)"><el-option v-for="unit in row.return_units" :key="unit.unit_id" :label="unit.unit_name" :value="unit.unit_id" /></el-select></template></el-table-column>
              <el-table-column label="本次退货数量" width="132"><template slot-scope="{row}"><el-input :value="row.requested_qty_input" size="mini" inputmode="decimal" placeholder="请输入" @input="handlePurchaseQtyInput(row,$event)" @blur="normalizePurchaseQty(row)" /></template></el-table-column>
              <el-table-column label="本次折合基本数量" width="150" align="right"><template slot-scope="{row}"><span class="qty-main">{{ formatQty(purchaseRequestedBaseQty(row), baseUnitPrecision(row)) }} {{ row.base_unit_name }}</span></template></el-table-column>
              <el-table-column label="设备编号" width="150" align="center"><template slot-scope="{row}"><span v-if="row.serial_tracking_mode==='none'">-</span><el-button v-else :type="row.serial_tracking_mode==='required'&&(row.serial_entries||[]).length!==serialRequiredCount(row)?'danger':'text'" size="mini" class="serial-select-button" @click="openSerialDialog(row)">{{ serialActionText(row) }}</el-button></template></el-table-column>
              <el-table-column label="备注" min-width="150"><template slot-scope="{row}"><el-input v-model.trim="row.remark" size="mini" maxlength="100" placeholder="请输入备注（非必填）" /></template></el-table-column>
              <el-table-column label="操作" width="64"><template slot-scope="{$index}"><el-button type="text" size="mini" class="danger" @click="removePurchaseLine($index)">删除</el-button></template></el-table-column>
            </el-table>
            <div class="selected-summary"><span>明细行数：{{ selectedLines.length }}</span><span>可退基本数量合计：{{ purchaseAvailableTotal }}</span><span>本次退货基本数量合计：{{ purchaseRequestedTotal }}</span></div>
          </div>

          <div class="purchase-warning"><i class="el-icon-warning" /><b>温馨提示：</b>采购退货单需提交并审核通过后，仓库完成出库过账，退货商品才会正式出库，库存数量才会减少，请知悉。</div>
        </main>

        <aside class="card check-card purchase-check-card"><h3>保存前检查</h3><p v-for="item in purchaseChecks" :key="item.text" :class="{ok:item.ok}"><i :class="item.ok ? 'el-icon-success' : 'el-icon-warning'" /> {{ item.text }}</p></aside>
      </div>

      <el-dialog title="选择退货设备编号" :visible.sync="serialDialog.visible" width="760px" append-to-body>
        <el-alert class="serial-required-alert" :closable="false" type="info" show-icon :title="serialDialogInstruction()" />
        <el-alert v-if="!serialDialog.loading&&serialDialog.total===0" class="serial-empty-alert" :closable="false" type="error" show-icon title="当前批次没有可用设备编号，请先核对入库编号状态，或取消占用该编号的未完成退货单。" />
        <div class="serial-dialog-summary"><span>{{ serialDialog.line&&serialDialog.line.item_code }} / {{ serialDialog.line&&serialDialog.line.item_name }}</span><b>应选 {{ serialRequiredCount(serialDialog.line) }} 个，已选 {{ serialDialog.draftEntries.length }} 个</b></div>
        <div class="serial-dialog-toolbar"><el-input v-model.trim="serialDialog.keyword" size="small" clearable placeholder="输入设备编号或厂家序列号" @keyup.enter.native="reloadSerials" /><el-button size="small" type="success" @click="reloadSerials">查询</el-button></div>
        <el-table v-loading="serialDialog.loading" :data="serialDialog.rows" border size="mini">
          <el-table-column label="选择" width="58" align="center"><template slot-scope="{row}"><el-checkbox :value="isSerialSelected(row)" @change="toggleSerial(row,$event)" /></template></el-table-column>
          <el-table-column prop="serial_no" label="设备编号 / 序列号" min-width="220" />
          <el-table-column prop="manufacturer_serial_no" label="厂家序列号" min-width="180"><template slot-scope="{row}">{{ row.manufacturer_serial_no||'-' }}</template></el-table-column>
          <el-table-column label="编号来源" width="110"><template slot-scope="{row}">{{ serialNumberSourceText(row.number_source) }}</template></el-table-column>
          <el-table-column label="状态" width="90"><template><el-tag size="mini" type="success">可用</el-tag></template></el-table-column>
        </el-table>
        <el-pagination background layout="total, prev, pager, next, sizes" :current-page.sync="serialDialog.page" :page-size.sync="serialDialog.per_page" :page-sizes="[10,20,50]" :total="serialDialog.total" @current-change="loadSerials" @size-change="reloadSerials" />
        <div slot="footer"><el-button size="small" @click="serialDialog.visible=false">取消</el-button><el-button size="small" type="success" :disabled="serialConfirmDisabled()" @click="confirmSerialSelection">{{ serialConfirmText() }}</el-button></div>
      </el-dialog>
    </template>

    <template v-else>
      <div class="design-action-row sales-action-row"><span class="design-crumb">销售管理　/　销售退货　/　<b>新建退货单</b></span><div><el-button size="small" icon="el-icon-back" @click="$router.push(basePath)">返回列表</el-button><el-button size="small" :loading="saving" @click="save(false)">保存草稿</el-button><el-button size="small" type="success" :loading="saving" @click="save(true)">保存并提交确认</el-button></div></div>
      <div class="sales-layout">
        <main class="sales-main">
          <div class="card sales-header-card">
            <div class="sales-header-col"><label>退货单号</label><el-input value="保存时按编号规则生成" size="small" disabled /><label>退货日期 <b>*</b></label><el-date-picker v-model="form.return_date" size="small" value-format="yyyy-MM-dd" style="width:100%" /></div>
            <div class="sales-header-col"><label>退货原因 <b>*</b></label><el-select v-model="form.return_reason" size="small" placeholder="请选择退货原因" style="width:100%"><el-option v-for="reason in salesReasons" :key="reason" :label="reason" :value="reason" /></el-select><label>备注</label><el-input v-model.trim="form.remark" type="textarea" :rows="2" maxlength="200" show-word-limit placeholder="请输入备注（选填）" /></div>
            <div class="order-snapshot"><h3>原销售订单信息（快照）</h3><dl><dt>订单号</dt><dd>{{ selectedSource&&selectedSource.sales_order_no||'-' }}</dd><dt>订单金额</dt><dd>{{ money(selectedSource&&selectedSource.order_amount) }}</dd><dt>客户名称</dt><dd>{{ selectedSource&&selectedSource.customer_name||'-' }}</dd><dt>已发货金额</dt><dd>{{ money(selectedSource&&selectedSource.shipped_amount) }}</dd><dt>下单日期</dt><dd>{{ selectedSource&&selectedSource.order_date||'-' }}</dd><dt>已申请退货金额</dt><dd>{{ money(selectedSource&&selectedSource.returned_amount) }}</dd></dl></div>
          </div>

          <div class="card sales-source-card">
            <h3>选择原销售订单</h3>
            <div class="sales-source-filter"><el-input v-model="sourceQuery.order_no" size="small" clearable placeholder="请输入订单号" @keyup.enter.native="reloadSources"><template slot="prepend">订单号</template></el-input><el-input v-model="sourceQuery.customer_keyword" size="small" clearable placeholder="请输入客户名称" @keyup.enter.native="reloadSources"><template slot="prepend">客户名称</template></el-input><el-date-picker v-model="sourceDateRange" size="small" type="daterange" value-format="yyyy-MM-dd" range-separator="~" start-placeholder="开始日期" end-placeholder="结束日期" /><el-select v-model="sourceQuery.shipment_status" clearable size="small" placeholder="订单状态"><el-option label="已发货" value="shipped" /><el-option label="部分发货" value="partial_shipped" /></el-select><el-button size="small" type="success" @click="reloadSources">查询</el-button><el-button size="small" @click="resetSourceFilters">重置</el-button></div>
            <el-table v-loading="loading" :data="sources" border size="mini" highlight-current-row @current-change="chooseSource"><el-table-column label="" width="48"><template slot-scope="{row}"><el-radio v-model="selectedSourceId" :label="row.id" @change="chooseSource(row)"><span /></el-radio></template></el-table-column><el-table-column prop="sales_order_no" label="订单号" min-width="160" /><el-table-column prop="customer_name" label="客户名称" min-width="180" /><el-table-column prop="order_date" label="下单日期" width="110" /><el-table-column label="订单金额" width="120" align="right"><template slot-scope="{row}">{{ money(row.order_amount) }}</template></el-table-column><el-table-column label="已发货金额" width="120" align="right"><template slot-scope="{row}">{{ money(row.shipped_amount) }}</template></el-table-column><el-table-column label="已申请退货金额" width="130" align="right"><template slot-scope="{row}">{{ money(row.returned_amount) }}</template></el-table-column><el-table-column prop="shipment_status" label="订单状态" width="100"><template><el-tag size="mini" type="success">已发货</el-tag></template></el-table-column></el-table>
            <el-pagination background layout="total, sizes, prev, pager, next, jumper" :current-page.sync="sourceQuery.page" :page-size.sync="sourceQuery.per_page" :page-sizes="[10,20,50]" :total="sourceTotal" @current-change="loadSources" @size-change="reloadSources" />
          </div>

          <div class="card sales-lines-card"><h3>所选订单明细 <small>（基于原履约 Item 快照）</small></h3><el-table :data="selectedLines" border size="mini"><el-table-column label="选择" width="58" align="center"><template slot-scope="{row}"><el-checkbox v-model="row.selected" /></template></el-table-column><el-table-column prop="product_name" label="Product" min-width="135" /><el-table-column prop="sku_name" label="SKU" min-width="130" /><el-table-column label="原履约 Item" min-width="180"><template slot-scope="{row}">{{ row.item_code }} / {{ row.item_name }}</template></el-table-column><el-table-column prop="base_unit_name" label="销售单位" width="85" /><el-table-column prop="shipped_qty" label="已发货" width="85" align="right" /><el-table-column prop="reserved_return_qty" label="已申请退货" width="95" align="right" /><el-table-column prop="available_return_qty" label="可退" width="80" align="right" /><el-table-column label="本次退货数量 *" width="130"><template slot-scope="{row}"><el-input-number v-model="row.requested_qty" size="mini" :min="0" :max="Number(row.available_return_qty)" :precision="2" :controls="false" :disabled="!row.selected" /></template></el-table-column><el-table-column label="换算后基本数量" width="125" align="right"><template slot-scope="{row}">{{ (Number(row.requested_qty||0)*Number(row.fulfillment_factor_snapshot||1)).toFixed(2) }}</template></el-table-column><el-table-column label="备注" min-width="150"><template slot-scope="{row}"><el-input v-model.trim="row.remark" size="mini" maxlength="100" placeholder="请输入（选填）" :disabled="!row.selected" /></template></el-table-column><el-table-column label="删除" width="55" align="center"><template slot-scope="{$index}"><el-button type="text" icon="el-icon-delete" class="danger" @click="selectedLines.splice($index,1)" /></template></el-table-column></el-table><el-pagination background layout="total, sizes, prev, pager, next, jumper" :current-page="1" :page-size="20" :total="selectedLines.length" /></div>
          <el-alert :closable="false" type="info" show-icon title="说明：调整本次退货数量或当前商品 SKU 默认的 Item，不会改变退货物料。退货物料始终以原履约 Item 快照为准。" />
        </main>
        <aside class="card check-card sales-check-card"><h3>退货校验结果</h3><p v-for="item in checks" :key="item.text" :class="{ok:item.ok}"><i :class="item.ok ? 'el-icon-success' : 'el-icon-warning'" /><span><b>{{ item.text }}</b><small>{{ item.hint }}</small></span></p></aside>
      </div>
    </template>
  </section>
</template>

<script>
import { createPurchaseReturn, listPurchaseReturnSources, listPurchaseReturnSourceSerials, submitPurchaseReturn } from '@/api/erp/purchase'
import { confirmSalesReturn, createSalesReturn, listSalesReturnSources } from '@/api/erp/sales'
export default {
  props:{ kind:{type:String,required:true} },
  data:()=>({ saving:false,loading:false,sources:[],sourceTotal:0,selectedSource:null,selectedSourceId:null,selectedLines:[],sourceDateRange:[],sourceQuery:{keyword:'',order_no:'',customer_keyword:'',shipment_status:'',page:1,per_page:10},serialDialog:{visible:false,loading:false,line:null,rows:[],total:0,keyword:'',page:1,per_page:10,draftEntries:[]},purchaseReasons:['质量问题','采购错误','规格不符','包装破损','供应商责任','其他'],salesReasons:['商品质量问题','客户多发','包装破损','发错商品','客户拒收','其他'],form:{return_date:(()=>{const date=new Date();const offset=date.getTimezoneOffset()*60000;return new Date(date.getTime()-offset).toISOString().slice(0,10)})(),return_reason:'',remark:''} }),
  computed:{
    title(){return this.kind==='purchase'?'采购退货':'销售退货'}, basePath(){return this.kind==='purchase'?'/purchase/returns':'/sales/returns'},
    activeLines(){return this.kind==='sales'?this.selectedLines.filter(r=>r.selected):this.selectedLines},
    checks(){return [{text:this.kind==='purchase'?'已选择同一供应商的原采购批次':'原订单已发货',hint:this.kind==='sales'?'订单已完成发货，可发起退货。':'',ok:!!this.selectedSource},{text:this.kind==='purchase'?'已选择至少一条退货明细':'使用原履约 Item 快照',hint:this.kind==='sales'?'基于原履约 Item 信息进行退货。':'',ok:this.activeLines.length>0&&this.activeLines.every(r=>this.kind==='purchase'||r.item_id)},{text:'退货数量为正数',hint:this.kind==='sales'?'本次退货数量均大于 0。':'',ok:this.activeLines.length>0&&this.activeLines.every(r=>Number(r.requested_qty)>0)},{text:'累计退货数量未超出已发货',hint:this.kind==='sales'?'所选商品累计退货数量未超出已发货数量。':'',ok:this.activeLines.length>0&&this.activeLines.every(r=>this.kind==='purchase'?this.purchaseRequestedBaseQty(r)<=Number(r.available_return_base_qty):Number(r.requested_qty)<=Number(r.available_return_qty))},{text:'不存在重复明细',hint:this.kind==='sales'?'所选商品在退货单中未重复添加。':'',ok:new Set(this.activeLines.map(r=>this.kind==='purchase'?r.inventory_transaction_item_id:r.sales_order_line_id)).size===this.activeLines.length}]},
    purchaseChecks(){const validQty=this.selectedLines.length>0&&this.selectedLines.every(r=>Number(r.requested_qty)>0&&r.return_unit_id);const within=this.selectedLines.length>0&&this.selectedLines.every(r=>this.purchaseRequestedBaseQty(r)<=Number(r.available_return_base_qty));const oneReceipt=this.selectedLines.length>0&&new Set(this.selectedLines.map(r=>r.source_receipt_id)).size===1;const serialsOk=this.selectedLines.length>0&&this.selectedLines.every(r=>r.serial_tracking_mode!=='required'||((r.serial_entries||[]).length===this.serialRequiredCount(r)));return[{text:'供应商一致性校验通过',ok:!!this.selectedSource&&oneReceipt},{text:'同一到货单多明细校验通过',ok:oneReceipt},{text:'原始到货批次校验通过',ok:this.selectedLines.length>0&&this.selectedLines.every(r=>r.source_receipt_item_id&&r.batch_no)},{text:'退货数量和单位完整',ok:validQty},{text:'本次折合基本数量不超过实际可退数量',ok:within},{text:'必需设备编号的明细已逐件选择',ok:serialsOk},{text:'未选择重复的原始到货批次',ok:new Set(this.selectedLines.map(r=>r.inventory_transaction_item_id)).size===this.selectedLines.length}]},
    purchaseAvailableTotal(){return this.selectedLines.reduce((sum,row)=>sum+Number(row.available_return_base_qty||0),0).toFixed(2)},
    purchaseRequestedTotal(){return this.selectedLines.reduce((sum,row)=>sum+this.purchaseRequestedBaseQty(row),0).toFixed(2)}
  },
  created(){this.loadSources()},
  methods:{
    async loadSources(){this.loading=true;try{const params={...this.sourceQuery,order_date_from:this.sourceDateRange&&this.sourceDateRange[0],order_date_to:this.sourceDateRange&&this.sourceDateRange[1]};const {data}=await(this.kind==='purchase'?listPurchaseReturnSources(params):listSalesReturnSources(params));this.sources=data.data||[];this.sourceTotal=data.total||0}finally{this.loading=false}}, reloadSources(){this.sourceQuery.page=1;this.loadSources()},
    resetSourceFilters(){this.sourceDateRange=[];this.sourceQuery={keyword:'',order_no:'',customer_keyword:'',shipment_status:'',page:1,per_page:10};this.loadSources()},
    chooseSource(row){if(!row||this.kind==='purchase')return;this.selectedSource=row;this.selectedSourceId=row.id;this.selectedLines=(row.lines||[]).filter(line=>Number(line.available_return_qty)>0).map(line=>({...line,selected:true,requested_qty:Number(line.available_return_qty),remark:''}))},
    isPurchaseSourceSelected(row){return this.selectedLines.some(line=>Number(line.inventory_transaction_item_id)===Number(row.inventory_transaction_item_id))},
    togglePurchaseSource(row,checked){const index=this.selectedLines.findIndex(line=>Number(line.inventory_transaction_item_id)===Number(row.inventory_transaction_item_id));if(!checked){if(index>=0)this.removePurchaseLine(index);return}if(index>=0)return;if(this.purchaseSourceBlocked(row))return this.$message.error(this.purchaseSourceBlockedReason(row));if(this.selectedLines.length&&Number(this.selectedLines[0].source_receipt_id)!==Number(row.source_receipt_id)){this.$message.error('一张采购退货单只能选择同一张原到货单的明细');return}const units=row.return_units||[];const base=units.find(unit=>unit.unit_type==='base')||units[0];const line={...row,return_unit_id:base&&base.unit_id,return_conversion_factor:Number(base&&base.conversion_factor||1),requested_qty:null,requested_qty_input:'',serial_entries:[],remark:''};this.selectedLines.push(line);this.selectedSource=this.selectedLines[0]},
    purchaseSourceSerialBlocked(row){return !!row&&row.serial_tracking_mode==='required'&&Number(row.available_serial_count||0)<=0},
    purchaseSourceBlocked(row){return Number(row&&row.available_return_base_qty||0)<=0||this.purchaseSourceSerialBlocked(row)},
    purchaseSourceBlockedReason(row){if(this.purchaseSourceSerialBlocked(row))return '当前批次没有可用设备编号，不能直接退货';return '当前批次库存已被订单、工单或质量处理占用，没有可退数量'},
    removePurchaseLine(index){this.selectedLines.splice(index,1);this.selectedSource=this.selectedLines[0]||null},
    changePurchaseReturnUnit(row,unitId){const hadQuantity=Number(row.requested_qty)>0;const previousBase=this.purchaseRequestedBaseQty(row);const unit=(row.return_units||[]).find(item=>Number(item.unit_id)===Number(unitId));const factor=Number(unit&&unit.conversion_factor||1);this.$set(row,'return_conversion_factor',factor);if(!hadQuantity){this.$set(row,'requested_qty',null);this.$set(row,'requested_qty_input','');return}const precision=this.returnUnitPrecision(row);const converted=this.floorToPrecision(previousBase/factor,precision);const next=Math.min(this.purchaseReturnMax(row),converted);this.$set(row,'requested_qty',next);this.$set(row,'requested_qty_input',String(next))},
    purchaseRequestedBaseQty(row){return this.roundToPrecision(Number(row.requested_qty||0)*Number(row.return_conversion_factor||1),this.baseUnitPrecision(row))},
    purchaseReturnMax(row){return this.floorToPrecision(Number(row.available_return_base_qty||0)/Number(row.return_conversion_factor||1),this.returnUnitPrecision(row))},
    returnUnitPrecision(row){const unit=(row.return_units||[]).find(item=>Number(item.unit_id)===Number(row.return_unit_id));return Math.min(8,Math.max(0,Number(unit&&unit.decimal_places!=null?unit.decimal_places:4)))},
    baseUnitPrecision(row){const unit=(row.return_units||[]).find(item=>item.unit_type==='base');return Math.min(8,Math.max(0,Number(unit&&unit.decimal_places!=null?unit.decimal_places:4)))},
    returnUnitName(row){const unit=(row.return_units||[]).find(item=>Number(item.unit_id)===Number(row.return_unit_id));return unit&&unit.unit_name||row.base_unit_name||''},
    purchaseReturnRemainder(row){const represented=this.purchaseReturnMax(row)*Number(row.return_conversion_factor||1);return Math.max(0,this.roundToPrecision(Number(row.available_return_base_qty||0)-represented,this.baseUnitPrecision(row)))},
    floorToPrecision(value,precision){const scale=Math.pow(10,precision);return Math.floor((Number(value||0)+Number.EPSILON)*scale)/scale},
    roundToPrecision(value,precision){const scale=Math.pow(10,precision);return Math.round((Number(value||0)+Number.EPSILON)*scale)/scale},
    formatQty(value,precision){return Number(value||0).toLocaleString('zh-CN',{minimumFractionDigits:0,maximumFractionDigits:precision})},
    serialRequiredCount(row){if(!row||row.serial_tracking_mode==='none')return 0;const qty=this.purchaseRequestedBaseQty(row);return Math.max(0,Math.round(qty))},
    serialSelectedCount(row){return (row&&row.serial_entries||[]).length},
    serialActionText(row){const selected=this.serialSelectedCount(row);const required=this.serialRequiredCount(row);if(!(Number(row.requested_qty)>0))return '请先填写退货数量';if(row.serial_tracking_mode!=='required')return selected===0?'选择编号（可选）':`已选 ${selected} 个`;return selected===0?`选择编号（必选 ${required} 个）`:`已选 ${selected}/${required} 个`},
    serialConfirmDisabled(){const line=this.serialDialog.line;return !!line&&line.serial_tracking_mode==='required'&&this.serialDialog.draftEntries.length!==this.serialRequiredCount(line)},
    serialDialogInstruction(){return this.serialDialog.line&&this.serialDialog.line.serial_tracking_mode==='required'?'必管编号物料必须逐件选择本批次当前可用编号；确认后才能保存退货单。':'可按实际退货实物选择本批次当前可用编号。'},
    serialConfirmText(){const line=this.serialDialog.line;return line&&line.serial_tracking_mode==='required'?`确认选择（${this.serialDialog.draftEntries.length}/${this.serialRequiredCount(line)}）`:'确认选择'},
    serialNumberSourceText(value){return({system_generated:'系统生成',supplier:'供应商编号',manufacturer:'厂家编号',manual:'手工录入'})[value]||value||'-'},
    async openSerialDialog(row){if(!(Number(row.requested_qty)>0))return this.$message.error('请先填写本次退货数量，再选择设备编号');const required=this.serialRequiredCount(row);if(row.serial_tracking_mode==='required'&&Math.abs(this.purchaseRequestedBaseQty(row)-required)>0.00000001)return this.$message.error('必需设备编号的物料必须按整数件退货');this.serialDialog.line=row;this.serialDialog.keyword='';this.serialDialog.page=1;this.serialDialog.draftEntries=(row.serial_entries||[]).map(entry=>({...entry}));this.serialDialog.visible=true;await this.loadSerials()},
    async loadSerials(){if(!this.serialDialog.line)return;this.serialDialog.loading=true;try{const {data}=await listPurchaseReturnSourceSerials(this.serialDialog.line.inventory_transaction_item_id,{keyword:this.serialDialog.keyword,page:this.serialDialog.page,per_page:this.serialDialog.per_page});this.serialDialog.rows=data.data||[];this.serialDialog.total=data.total||0}finally{this.serialDialog.loading=false}},
    reloadSerials(){this.serialDialog.page=1;this.loadSerials()},
    isSerialSelected(row){return this.serialDialog.draftEntries.some(entry=>Number(entry.id)===Number(row.id))},
    toggleSerial(row,checked){const index=this.serialDialog.draftEntries.findIndex(entry=>Number(entry.id)===Number(row.id));if(!checked){if(index>=0)this.serialDialog.draftEntries.splice(index,1);return}if(index>=0)return;const required=this.serialRequiredCount(this.serialDialog.line);if(this.serialDialog.draftEntries.length>=required){this.$message.warning(`本次退货只需选择 ${required} 个设备编号`);return}this.serialDialog.draftEntries.push({...row})},
    confirmSerialSelection(){const line=this.serialDialog.line;const required=this.serialRequiredCount(line);if(line&&line.serial_tracking_mode==='required'&&this.serialDialog.draftEntries.length!==required)return this.$message.error(`本次退货 ${required} 件，必须选择 ${required} 个设备编号`);this.$set(line,'serial_entries',this.serialDialog.draftEntries.map(entry=>({...entry})));this.serialDialog.visible=false},
    purchaseReturnMin(row){return 1/Math.pow(10,this.returnUnitPrecision(row))},
    handlePurchaseQtyInput(row,value){const raw=String(value==null?'':value).replace(/[^0-9.]/g,'');const firstDot=raw.indexOf('.');const cleaned=firstDot<0?raw:raw.slice(0,firstDot+1)+raw.slice(firstDot+1).replace(/\./g,'');this.$set(row,'requested_qty_input',cleaned);const numeric=cleaned!==''&&cleaned!=='.'?Number(cleaned):NaN;this.$set(row,'requested_qty',Number.isFinite(numeric)?numeric:null);this.handlePurchaseQtyChange(row)},
    normalizePurchaseQty(row){const numeric=Number(row.requested_qty);if(!(numeric>0)){this.$set(row,'requested_qty',null);this.$set(row,'requested_qty_input','');this.handlePurchaseQtyChange(row);return}const precision=this.returnUnitPrecision(row);const normalized=Math.min(this.purchaseReturnMax(row),Math.max(this.purchaseReturnMin(row),this.floorToPrecision(numeric,precision)));this.$set(row,'requested_qty',normalized);this.$set(row,'requested_qty_input',String(normalized));this.handlePurchaseQtyChange(row)},
    handlePurchaseQtyChange(row){if(!row||row.serial_tracking_mode==='none')return;const required=this.serialRequiredCount(row);if((row.serial_entries||[]).length>required)this.$set(row,'serial_entries',row.serial_entries.slice(0,required))},
    payload(){if(this.kind==='purchase')return{...this.form,return_scope:'posted_inventory',source_receipt_id:this.selectedSource&&this.selectedSource.source_receipt_id,supplier_id:this.selectedSource&&this.selectedSource.supplier_id,items:this.selectedLines.map(row=>({source_receipt_item_id:row.source_receipt_item_id,warehouse_id:row.warehouse_id,location_id:row.location_id,batch_no:row.batch_no,requested_return_qty:row.requested_qty,return_unit_id:row.return_unit_id,serial_ids:(row.serial_entries||[]).map(entry=>entry.id),remark:row.remark||null}))};return{...this.form,sales_order_id:this.selectedSource&&this.selectedSource.id,items:this.activeLines.map(row=>({sales_order_line_id:row.sales_order_line_id,requested_sales_qty:row.requested_qty,remark:row.remark||null}))}},
    money(value){return `¥ ${Number(value||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`},
    async save(advance){const validations=this.kind==='purchase'?this.purchaseChecks:this.checks;if(!this.form.return_reason||!validations.every(item=>item.ok))return this.$message.error('请先补全退货原因、业务来源、合法数量和设备编号');this.saving=true;try{const response=await(this.kind==='purchase'?createPurchaseReturn(this.payload()):createSalesReturn(this.payload()));const row=response.data.data||response.data;if(advance)await(this.kind==='purchase'?submitPurchaseReturn(row.id):confirmSalesReturn(row.id));this.$message.success(advance?'已保存并进入下一状态':'草稿已保存');this.$router.replace(`${this.basePath}/${row.id}/detail`)}finally{this.saving=false}}
  }
}
